long long getMinimumTime(int n, vector<int>& high_priority,
                         int normal_time, int priority_time) {

    sort(high_priority.begin(), high_priority.end());

    function<long long(int, int)> solve = [&](int l, int r) -> long long {

        int cnt = lower_bound(high_priority.begin(), high_priority.end(), r + 1)
                - lower_bound(high_priority.begin(), high_priority.end(), l);

        // No high-priority processes
        if (cnt == 0)
            return normal_time;

        // Cost of executing the entire segment
        long long cost = 1LL * priority_time * cnt * (r - l + 1);

        // Cannot divide further
        if (l == r)
            return cost;

        // Divide into two equal segments
        int mid = (l + r) / 2;

        long long splitCost = solve(l, mid) + solve(mid + 1, r);

        return min(cost, splitCost);
    };

    return solve(1, n);
}
